/// <summary>
/// Per warehouse: where its wall-to-wall counts start (HSMobileOpsCountWallToWall), under which
/// journal name, and whether its counts are assortment based (HSMobileOpsCountAssortment).
/// </summary>
public class HSMobileOpsCountWarehouse extends common
{
}

Method.Source:
public static HSMobileOpsCountWarehouse find(InventLocationId _warehouse, boolean _forUpdate = false)
{
    HSMobileOpsCountWarehouse row;

    row.selectForUpdate(_forUpdate);
    select firstOnly row
        where row.Warehouse == _warehouse;
    return row;
}

/// <summary>The warehouse's wall-to-wall count, while it is frozen.</summary>
[SysClientCacheDataMethodAttribute(false)]
public display str 30 w2wStatus()
{
    HSMobileOpsWarehouseFreeze freeze = HSMobileOpsWarehouseFreeze::findActive(this.Warehouse);

    return freeze.RecId ? enum2Str(freeze.Status) : '';
}

/// <summary>What the current wall-to-wall count last did, else how the last one ended.</summary>
[SysClientCacheDataMethodAttribute(false)]
public display str 250 w2wMessage()
{
    HSMobileOpsWarehouseFreeze freeze = HSMobileOpsWarehouseFreeze::findActive(this.Warehouse);

    if (!freeze.RecId)
    {
        select firstOnly freeze
            order by StartedUtc desc
            where freeze.InventLocationId == this.Warehouse;
    }
    return freeze.Message;
}
